-- MathLabs V4 — Primera unidad escolar completa
-- Requiere MathLabs V1, V2 abierto y V3.
begin;

-- Permitir unidades escolares sin mezclar su identidad con M1/M2.
alter table public.learning_units drop constraint if exists learning_units_test_type_check;
alter table public.learning_units add constraint learning_units_test_type_check check (test_type in ('M1','M2','SCHOOL'));

-- Tipos de bloques para lecciones profundas.
alter table public.lesson_blocks drop constraint if exists lesson_blocks_block_type_check;
alter table public.lesson_blocks add constraint lesson_blocks_block_type_check check (block_type in ('objective','text','concepts','formula','visual','examples','common_errors','tip','summary','video','practice','prerequisites','strategy','guided_practice'));

-- Banco seguro de práctica escolar.
create table if not exists public.school_practice_items (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  course_id text not null references public.courses(id) on delete cascade,
  topic_id text not null references public.knowledge_topics(id) on delete cascade,
  prompt text not null,
  options jsonb not null check (jsonb_typeof(options) = 'array'),
  correct_option text not null check (correct_option in ('A','B','C','D')),
  explanation text not null default '',
  feedback_by_option jsonb not null default '{}'::jsonb,
  difficulty text not null check (difficulty in ('Fundamental','Intermedio','Avanzado')),
  skill text not null check (skill in ('Resolver problemas','Modelar','Representar','Argumentar')),
  sort_order integer not null default 0,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.school_practice_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null references public.courses(id) on delete cascade,
  topic_id text not null references public.knowledge_topics(id) on delete cascade,
  status text not null default 'active' check (status in ('active','completed','abandoned')),
  total_questions integer not null default 0,
  correct_answers integer not null default 0,
  score_percent integer not null default 0 check (score_percent between 0 and 100),
  started_at timestamptz not null default now(),
  completed_at timestamptz
);
create table if not exists public.school_practice_session_items (
  session_id uuid not null references public.school_practice_sessions(id) on delete cascade,
  item_id uuid not null references public.school_practice_items(id) on delete cascade,
  position integer not null,
  primary key (session_id, item_id),
  unique (session_id, position)
);
create table if not exists public.school_practice_responses (
  session_id uuid not null references public.school_practice_sessions(id) on delete cascade,
  item_id uuid not null references public.school_practice_items(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  selected_option text not null check (selected_option in ('A','B','C','D')),
  is_correct boolean not null,
  confidence_level text not null default 'unsure' check (confidence_level in ('unsure','somewhat','confident')),
  time_seconds integer not null default 0 check (time_seconds between 0 and 7200),
  answered_at timestamptz not null default now(),
  primary key (session_id, item_id)
);
create index if not exists school_practice_items_topic_idx on public.school_practice_items(topic_id, is_published, difficulty, sort_order);
create index if not exists school_practice_sessions_user_idx on public.school_practice_sessions(user_id, started_at desc);

alter table public.school_practice_items enable row level security;
alter table public.school_practice_sessions enable row level security;
alter table public.school_practice_session_items enable row level security;
alter table public.school_practice_responses enable row level security;

drop policy if exists "Public reads published school practice items" on public.school_practice_items;
drop policy if exists "Admins manage school practice items" on public.school_practice_items;
create policy "Admins manage school practice items" on public.school_practice_items for all to authenticated using (public.is_learning_admin()) with check (public.is_learning_admin());
drop policy if exists "Users read own school practice sessions" on public.school_practice_sessions;
create policy "Users read own school practice sessions" on public.school_practice_sessions for select to authenticated using (user_id = auth.uid() or public.is_learning_admin());
drop policy if exists "Users read own school practice session items" on public.school_practice_session_items;
create policy "Users read own school practice session items" on public.school_practice_session_items for select to authenticated using (
  exists (select 1 from public.school_practice_sessions s where s.id = session_id and (s.user_id = auth.uid() or public.is_learning_admin()))
);
drop policy if exists "Users read own school practice responses" on public.school_practice_responses;
create policy "Users read own school practice responses" on public.school_practice_responses for select to authenticated using (user_id = auth.uid() or public.is_learning_admin());

revoke all on public.school_practice_items, public.school_practice_sessions, public.school_practice_session_items, public.school_practice_responses from anon;
revoke all on public.school_practice_items, public.school_practice_sessions, public.school_practice_session_items, public.school_practice_responses from authenticated;
grant select, insert, update, delete on public.school_practice_items to authenticated;
grant select on public.school_practice_sessions, public.school_practice_session_items, public.school_practice_responses to authenticated;
grant insert, update, delete on public.school_practice_items to authenticated;

-- Unidad y lecciones escolares.
insert into public.learning_units (id,test_type,axis,slug,title,description,icon,sort_order,is_published)
values ('school-5b-numeros-operaciones','SCHOOL','Números y operaciones','5-basico-numeros-operaciones','5.º básico · Números y operaciones','Primera ruta escolar completa: valor posicional, cálculo mental, multiplicación, división, operatoria combinada y problemas.','5°',1,true)
on conflict (id) do update set test_type=excluded.test_type, axis=excluded.axis, slug=excluded.slug, title=excluded.title, description=excluded.description, icon=excluded.icon, sort_order=excluded.sort_order, is_published=excluded.is_published;
insert into public.lessons (id,unit_id,slug,title,summary,objective,estimated_minutes,difficulty,sort_order,is_published,video_url,thumbnail_url,prerequisites,tags,question_filter)
values
('school-5b-num-01','school-5b-numeros-operaciones','5b-numeros-naturales-valor-posicional','Números naturales y valor posicional','Lee, representa, compone, descompone, aproxima, compara y ordena números naturales menores que mil millones.','Comprender que el valor de un dígito depende de su posición y usar esa idea para representar y comparar números grandes.',48,'Básico',1,true,null,null,'{}'::text[],array['5 básico','valor posicional','números naturales','redondeo']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-01", "topic_slug": "numeros-naturales-valor-posicional"}'::jsonb),
('school-5b-num-02','school-5b-numeros-operaciones','5b-estrategias-calculo-mental','Estrategias de cálculo mental','Multiplica con rapidez usando múltiplos de 10, dobles, mitades y propiedades de las operaciones.','Elegir y explicar estrategias eficientes de multiplicación mental en vez de depender siempre del algoritmo escrito.',46,'Básico',2,true,null,null,array['school-5b-num-01']::text[],array['5 básico','cálculo mental','multiplicación','propiedades']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-02", "topic_slug": "estrategias-de-calculo-mental"}'::jsonb),
('school-5b-num-03','school-5b-numeros-operaciones','5b-multiplicacion-dos-digitos','Multiplicación de dos dígitos','Estima y resuelve multiplicaciones de dos dígitos mediante modelos, productos parciales y algoritmo.','Comprender por qué funciona el algoritmo y aplicar la multiplicación en problemas rutinarios y no rutinarios.',52,'Básico',3,true,null,null,array['school-5b-num-02']::text[],array['5 básico','multiplicación','productos parciales','estimación']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-03", "topic_slug": "multiplicacion-de-dos-digitos"}'::jsonb),
('school-5b-num-04','school-5b-numeros-operaciones','5b-division-interpretacion-resto','División e interpretación del resto','Resuelve divisiones con dividendos de tres dígitos y decide qué significa el resto en cada contexto.','Comprender la división como reparto y agrupamiento, aplicar el algoritmo e interpretar el resto según el problema.',54,'Básico',4,true,null,null,array['school-5b-num-03']::text[],array['5 básico','división','resto','problemas']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-04", "topic_slug": "division-e-interpretacion-del-resto"}'::jsonb),
('school-5b-num-05','school-5b-numeros-operaciones','5b-operatoria-combinada','Operatoria combinada','Resuelve expresiones con las cuatro operaciones, paréntesis y prioridad operacional.','Comprender que la convención de prioridad evita resultados ambiguos y aplicarla con orden y verificación.',48,'Básico',5,true,null,null,array['school-5b-num-03','school-5b-num-04']::text[],array['5 básico','operatoria combinada','paréntesis','prioridad']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-05", "topic_slug": "operatoria-combinada"}'::jsonb),
('school-5b-num-06','school-5b-numeros-operaciones','5b-problemas-cuatro-operaciones','Problemas con las cuatro operaciones','Resuelve problemas de una y varias etapas, seleccionando datos, operaciones, representaciones y comprobaciones.','Modelar problemas rutinarios y no rutinarios con combinaciones de operaciones y comunicar una solución completa.',56,'Medio',6,true,null,null,array['school-5b-num-05']::text[],array['5 básico','resolución de problemas','modelar','cuatro operaciones']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-06", "topic_slug": "problemas-con-las-cuatro-operaciones"}'::jsonb)
on conflict (id) do update set unit_id=excluded.unit_id, slug=excluded.slug, title=excluded.title, summary=excluded.summary, objective=excluded.objective, estimated_minutes=excluded.estimated_minutes, difficulty=excluded.difficulty, sort_order=excluded.sort_order, is_published=excluded.is_published, prerequisites=excluded.prerequisites, tags=excluded.tags, question_filter=excluded.question_filter;

delete from public.lesson_blocks where lesson_id in ('school-5b-num-01','school-5b-num-02','school-5b-num-03','school-5b-num-04','school-5b-num-05','school-5b-num-06');
insert into public.lesson_blocks (lesson_id,block_type,title,content,data,sort_order) values
('school-5b-num-01','objective','Meta de aprendizaje','Al terminar podrás explicar el valor de cada dígito, representar un número de varias formas, aproximarlo y compararlo con otros.','{}'::jsonb,1),
('school-5b-num-01','prerequisites','Antes de comenzar','Activa estas ideas.','{"items":[{"title":"Unidades, decenas y centenas","body":"Cada posición vale diez veces la que está a su derecha."},{"title":"Lectura de números","body":"Separa mentalmente el número en grupos de tres cifras."},{"title":"Recta numérica","body":"Los números aumentan hacia la derecha."}]}'::jsonb,2),
('school-5b-num-01','text','La idea central: la posición cambia el valor','En el número 407 215 036, el dígito 4 representa cuatrocientos millones, mientras que el 4 escrito en otra posición podría representar cuarenta mil o cuatro unidades. El dígito es el símbolo; su valor posicional depende del lugar que ocupa.

La forma estándar escribe el número con cifras. La forma expandida muestra cuánto aporta cada dígito: 52 304 018 = 50 000 000 + 2 000 000 + 300 000 + 4 000 + 10 + 8. Los ceros también son importantes porque conservan las posiciones vacías.

Para comparar números, primero observa la cantidad de cifras. Si tienen la misma cantidad, compara de izquierda a derecha hasta encontrar la primera diferencia. Para aproximar, identifica la posición solicitada y observa el dígito inmediatamente a su derecha: de 0 a 4 se mantiene; de 5 a 9 aumenta una unidad.','{}'::jsonb,3),
('school-5b-num-01','concepts','Representaciones que debes dominar','','{"items":[{"title":"Forma estándar","body":"Usa cifras y separadores de miles: 38 405 207."},{"title":"Forma expandida","body":"Muestra el aporte de cada posición."},{"title":"Forma verbal","body":"Expresa el número con palabras."},{"title":"Aproximación","body":"Reemplaza por un valor cercano y útil según una posición elegida."}]}'::jsonb,4),
('school-5b-num-01','formula','Tabla de valor posicional','','{"items":["Centena de millón = 100 000 000","Decena de millón = 10 000 000","Unidad de millón = 1 000 000","Centena de mil = 100 000","Decena de mil = 10 000","Unidad de mil = 1 000"]}'::jsonb,5),
('school-5b-num-01','strategy','Método para leer y comparar números grandes','','{"steps":[{"title":"1. Separa en grupos de tres","body":"Desde la derecha: unidades, miles y millones."},{"title":"2. Identifica el primer dígito no nulo","body":"Te indica el orden de magnitud."},{"title":"3. Compara de izquierda a derecha","body":"La primera diferencia decide cuál es mayor."},{"title":"4. Comprueba con una estimación","body":"Redondea para verificar que el orden tenga sentido."}]}'::jsonb,6),
('school-5b-num-01','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"¿Qué valor representa el dígito 7 en 372 415 008?","steps":["El 7 está en la decena de millón.","Una decena de millón equivale a 10 000 000.","Multiplicamos 7 por 10 000 000."],"answer":"70 000 000","skill":"Representar","level":"Fundamental","strategy":"Ubica la columna antes de calcular.","verification":"372 415 008 está entre 300 y 400 millones; 70 millones es un aporte coherente."},{"problem":"Escribe 406 032 en forma expandida.","steps":["El 4 está en centenas de mil.","El 6 está en unidades de mil.","El 3 está en decenas y el 2 en unidades."],"answer":"400 000 + 6 000 + 30 + 2","skill":"Representar","level":"Fundamental","strategy":"Omite términos cuyo dígito es cero.","verification":"La suma vuelve a producir 406 032."}]}'::jsonb,7),
('school-5b-num-01','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Ordena de menor a mayor: 45 980 210; 45 908 210; 46 001 005.","steps":["Los dos primeros tienen 45 millones; el tercero tiene 46 millones y es el mayor.","Entre los de 45 millones comparamos centenas de mil: 9 en ambos.","Luego comparamos decenas de mil: 8 es mayor que 0."],"answer":"45 908 210 < 45 980 210 < 46 001 005","skill":"Argumentar","level":"Intermedio","strategy":"Compara una posición por vez.","verification":"La aproximación a millones da 46, 46 y 46 millones, por eso hay que mirar más posiciones."},{"problem":"Aproxima 683 749 a la decena de mil.","steps":["La decena de mil es el 8.","Observamos la unidad de mil, que es 3.","Como 3 es menor que 5, el 8 se mantiene y las cifras de la derecha pasan a cero."],"answer":"680 000","skill":"Resolver problemas","level":"Intermedio","strategy":"Subraya la posición a la que redondeas.","verification":"683 749 está más cerca de 680 000 que de 690 000."}]}'::jsonb,8),
('school-5b-num-01','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Con las cifras 2, 4, 5, 7, 8 y 9, sin repetir, forma el mayor número menor que 800 000.","steps":["La primera cifra debe ser menor que 8; elegimos la mayor disponible: 7.","Para maximizar el resto, ordenamos las cifras restantes de mayor a menor.","Quedan 9, 8, 5, 4 y 2."],"answer":"798 542","skill":"Argumentar","level":"Desafío","strategy":"Fija primero la cifra más importante.","verification":"Cualquier número que comience con 8 o 9 supera 800 000; entre los que comienzan con 7, este usa el mayor orden restante."},{"problem":"Una ciudad informa 2 948 670 habitantes. ¿Qué cifra es adecuada para comunicar una población aproximada a la centena de mil?","steps":["La centena de mil es el 9.","Observamos la decena de mil, que es 4.","Como 4 es menor que 5, mantenemos el 9."],"answer":"2 900 000 habitantes","skill":"Modelar","level":"Desafío","strategy":"La precisión depende del propósito de la información.","verification":"El valor exacto está a 48 670 de 2 900 000 y a 51 330 de 3 000 000."}]}'::jsonb,9),
('school-5b-num-01','guided_practice','Práctica guiada','Intenta cada desafío antes de abrir las pistas.','{"exercises":[{"problem":"¿Qué valor representa el 6 en 164 203 090?","hints":["Ubica el 6 desde la derecha.","Está en decenas de millón."],"steps":["6 × 10 000 000 = 60 000 000."],"answer":"60 000 000","skill":"Representar"},{"problem":"Escribe en forma estándar: 70 000 000 + 500 000 + 8 000 + 90 + 1.","hints":["Suma los aportes conservando las posiciones vacías.","Escribe grupos de tres cifras."],"steps":["70 000 000 + 500 000 = 70 500 000.","Agregando 8 000, 90 y 1 resulta 70 508 091."],"answer":"70 508 091","skill":"Representar"},{"problem":"Redondea 7 652 814 a la centena de mil.","hints":["La centena de mil es el 6.","Mira la decena de mil: 5."],"steps":["Como el dígito siguiente es 5, aumentamos 6 a 7.","Las cifras posteriores se reemplazan por cero."],"answer":"7 700 000","skill":"Resolver problemas"}]}'::jsonb,10),
('school-5b-num-01','common_errors','Errores frecuentes','','{"items":[{"title":"Confundir dígito con valor","description":"El dígito 5 puede valer 5, 50, 5 000 o más según su posición."},{"title":"Eliminar ceros internos","description":"En 405 020, los ceros mantienen las posiciones y no pueden omitirse."},{"title":"Comparar solo las últimas cifras","description":"La comparación comienza por la posición de mayor valor."},{"title":"Mirar el dígito equivocado al redondear","description":"Siempre se observa el dígito inmediatamente a la derecha de la posición solicitada."}]}'::jsonb,11),
('school-5b-num-01','summary','Dominio esperado','','{"items":["Identificas el valor de cualquier dígito.","Transformas entre forma estándar, verbal y expandida.","Comparas y ordenas números grandes.","Redondeas a la posición solicitada.","Justificas por qué un número es mayor que otro."]}'::jsonb,12),
('school-5b-num-01','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13),
('school-5b-num-02','objective','Meta de aprendizaje','Seleccionar una estrategia mental adecuada, explicar por qué funciona y comprobar el resultado mediante estimación.','{}'::jsonb,1),
('school-5b-num-02','prerequisites','Antes de comenzar','','{"items":[{"title":"Tablas de multiplicar","body":"Deben estar razonablemente disponibles para construir cálculos mayores."},{"title":"Valor posicional","body":"Multiplicar por 10, 100 o 1 000 desplaza el valor de cada cifra."},{"title":"Descomposición","body":"Un número puede separarse en sumas convenientes."}]}'::jsonb,2),
('school-5b-num-02','text','Calcular mentalmente es transformar el problema','El cálculo mental no significa hacer el algoritmo “en la cabeza”. Significa reemplazar una multiplicación difícil por otra equivalente y más sencilla.

Al multiplicar por 10, 100 o 1 000, cada cifra adquiere un valor diez, cien o mil veces mayor. La estrategia de dobles y mitades conserva el producto: si un factor se duplica y el otro se divide por dos, el resultado no cambia. Por ejemplo, 16 × 25 = 8 × 50 = 4 × 100.

La propiedad distributiva permite descomponer: 37 × 6 = (30 + 7) × 6 = 180 + 42. La conmutativa permite cambiar el orden y la asociativa reagrupar factores para formar productos fáciles.','{}'::jsonb,3),
('school-5b-num-02','concepts','Estrategias esenciales','','{"items":[{"title":"Anexar ceros con sentido","body":"Primero calcula con las cifras no nulas y luego considera el factor 10, 100 o 1 000."},{"title":"Doblar y dividir por dos","body":"Transforma un factor mientras compensas con el otro."},{"title":"Distribuir","body":"Separa un factor en una suma o diferencia conveniente."},{"title":"Reagrupar","body":"Busca pares como 25×4 o 50×2 para formar 100."}]}'::jsonb,4),
('school-5b-num-02','formula','Propiedades que justifican las estrategias','','{"items":["a·b = b·a","(a·b)·c = a·(b·c)","a·(b+c) = a·b + a·c","a·(b−c) = a·b − a·c","2a·(b/2) = a·b, cuando b es par"]}'::jsonb,5),
('school-5b-num-02','strategy','Cómo elegir una estrategia','','{"steps":[{"title":"1. Busca ceros o factores amigables","body":"10, 20, 25, 50, 100 y 1 000 suelen facilitar."},{"title":"2. Decide si conviene descomponer","body":"Separa en decenas y unidades o usa un número cercano."},{"title":"3. Calcula las partes","body":"Mantén un registro breve para no perder términos."},{"title":"4. Estima","body":"Comprueba el tamaño aproximado del producto."}]}'::jsonb,6),
('school-5b-num-02','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"Calcula mentalmente 34 × 20.","steps":["20 = 2 × 10.","34 × 2 = 68.","68 × 10 = 680."],"answer":"680","skill":"Resolver problemas","level":"Fundamental","strategy":"Separa el múltiplo de 10.","verification":"34×20 debe ser el doble de 34×10=340."},{"problem":"Calcula 25 × 16 usando dobles y mitades.","steps":["Dividimos 16 por 2 y duplicamos 25: 50 × 8.","Repetimos: 100 × 4.","100 × 4 = 400."],"answer":"400","skill":"Argumentar","level":"Fundamental","strategy":"Forma un factor 100.","verification":"25×4=100 y 16 contiene cuatro grupos de 4."}]}'::jsonb,7),
('school-5b-num-02','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Calcula 48 × 7 con la propiedad distributiva.","steps":["Descomponemos 48 = 40 + 8.","40×7=280 y 8×7=56.","Sumamos 280+56."],"answer":"336","skill":"Resolver problemas","level":"Intermedio","strategy":"Distribuye por decenas y unidades.","verification":"50×7=350; el resultado debe ser 14 menos, es decir 336."},{"problem":"Calcula 99 × 6 sin algoritmo.","steps":["Usamos 99 = 100 − 1.","100×6=600.","Restamos 1×6=6."],"answer":"594","skill":"Argumentar","level":"Intermedio","strategy":"Usa un número cercano y compensa.","verification":"594 está 6 unidades bajo 600."}]}'::jsonb,8),
('school-5b-num-02','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Calcula 125 × 24 mentalmente.","steps":["Descomponemos 24 = 3×8.","125×8=1 000.","1 000×3=3 000."],"answer":"3 000","skill":"Argumentar","level":"Desafío","strategy":"Reagrupa para formar 1 000.","verification":"125×20=2 500 y 125×4=500; suma 3 000."},{"problem":"Una caja tiene 48 paquetes y cada paquete contiene 25 fichas. ¿Cuántas fichas hay?","steps":["Modelamos 48×25.","Duplicamos 25 y dividimos 48 por 2: 50×24.","50×24 = 1 200."],"answer":"1 200 fichas","skill":"Modelar","level":"Desafío","strategy":"Transforma el producto antes de calcular.","verification":"25×4=100; 48 paquetes equivalen a 12 grupos de cuatro, es decir 1 200."}]}'::jsonb,9),
('school-5b-num-02','guided_practice','Práctica guiada','','{"exercises":[{"problem":"Calcula 36 × 50.","hints":["50 = 5×10.","36×5 puede hallarse como la mitad de 36×10."],"steps":["36×5=180.","180×10=1 800."],"answer":"1 800","skill":"Resolver problemas"},{"problem":"Calcula 72 × 9 usando un número cercano.","hints":["9 = 10−1.","Calcula 72×10 y resta 72."],"steps":["720−72=648."],"answer":"648","skill":"Argumentar"},{"problem":"Calcula 32 × 25.","hints":["Divide 32 por 4 y multiplica 25 por 4.","25×4=100."],"steps":["32×25 = 8×100."],"answer":"800","skill":"Resolver problemas"}]}'::jsonb,10),
('school-5b-num-02','common_errors','Errores frecuentes','','{"items":[{"title":"Anexar ceros sin considerar el factor","description":"En 34×20 se calcula 34×2 y luego se multiplica por 10; no se agrega un cero como regla aislada."},{"title":"Doblar solo un factor","description":"Para conservar el producto, si duplicas un factor debes dividir el otro por dos."},{"title":"Olvidar una parte al distribuir","description":"(40+8)×7 necesita 40×7 y 8×7."},{"title":"No estimar","description":"Una estimación detecta resultados con un cero de más o de menos."}]}'::jsonb,11),
('school-5b-num-02','summary','Dominio esperado','','{"items":["Multiplicas por múltiplos de 10 con comprensión.","Usas dobles y mitades conservando el producto.","Aplicas las propiedades conmutativa, asociativa y distributiva.","Eliges una estrategia eficiente.","Compruebas el resultado mediante estimación."]}'::jsonb,12),
('school-5b-num-02','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13),
('school-5b-num-03','objective','Meta de aprendizaje','Estimar productos, resolver multiplicaciones de dos dígitos y explicar el significado de cada producto parcial.','{}'::jsonb,1),
('school-5b-num-03','prerequisites','Antes de comenzar','','{"items":[{"title":"Tablas básicas","body":"Permiten calcular cada producto parcial."},{"title":"Descomposición decimal","body":"47 significa 40+7."},{"title":"Estimación","body":"Redondear permite anticipar el tamaño del resultado."}]}'::jsonb,2),
('school-5b-num-03','text','El algoritmo resume la distributiva','Multiplicar 36 × 24 equivale a multiplicar (30+6)(20+4). Aparecen cuatro productos: 30×20, 30×4, 6×20 y 6×4. El algoritmo tradicional organiza esos productos parciales de manera compacta.

Antes de calcular, estima. Si 36≈40 y 24≈20, el producto estará cerca de 800. Esta referencia ayuda a detectar errores.

En problemas, no basta con multiplicar: primero debes identificar qué representa cada factor y expresar la respuesta con su unidad.','{}'::jsonb,3),
('school-5b-num-03','concepts','Tres representaciones','','{"items":[{"title":"Modelo de área","body":"Divide un rectángulo según decenas y unidades."},{"title":"Productos parciales","body":"Calcula cada combinación de partes y luego suma."},{"title":"Algoritmo convencional","body":"Registra de forma abreviada los mismos productos parciales."},{"title":"Estimación","body":"Entrega un rango razonable antes del cálculo exacto."}]}'::jsonb,4),
('school-5b-num-03','formula','Descomposición del producto','','{"items":["(a+b)(c+d)=ac+ad+bc+bd","36×24 = 30×20 + 30×4 + 6×20 + 6×4","Producto aproximado ≈ factores redondeados multiplicados"]}'::jsonb,5),
('school-5b-num-03','strategy','Método seguro','','{"steps":[{"title":"1. Estima","body":"Redondea ambos factores."},{"title":"2. Calcula productos parciales","body":"Unidades por unidades y decenas."},{"title":"3. Alinea por valor posicional","body":"La segunda fila representa decenas, no unidades."},{"title":"4. Suma y compara con la estimación","body":"El resultado exacto debe ser razonable."}]}'::jsonb,6),
('school-5b-num-03','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"Calcula 23 × 14 usando productos parciales.","steps":["23×14 = 23×(10+4).","23×10=230.","23×4=92; sumamos 230+92."],"answer":"322","skill":"Resolver problemas","level":"Fundamental","strategy":"Descompón uno de los factores.","verification":"23×14 debe ser un poco mayor que 23×10=230."},{"problem":"Estima 47 × 32 redondeando a decenas.","steps":["47≈50.","32≈30.","50×30=1 500."],"answer":"Aproximadamente 1 500","skill":"Representar","level":"Fundamental","strategy":"La estimación no reemplaza el resultado exacto.","verification":"El producto exacto será cercano a 1 500."}]}'::jsonb,7),
('school-5b-num-03','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Calcula 47 × 32.","steps":["Descomponemos 32=30+2.","47×30=1 410.","47×2=94; sumamos."],"answer":"1 504","skill":"Resolver problemas","level":"Intermedio","strategy":"Mantén separados los productos por 30 y por 2.","verification":"La estimación 50×30=1 500 confirma el resultado."},{"problem":"Una sala tiene 28 filas con 34 asientos cada una. ¿Cuántos asientos hay?","steps":["La cantidad total es filas×asientos por fila: 28×34.","34×20=680 y 34×8=272.","680+272=952."],"answer":"952 asientos","skill":"Modelar","level":"Intermedio","strategy":"Identifica grupos iguales.","verification":"Aproximando 30×30 se esperan cerca de 900 asientos."}]}'::jsonb,8),
('school-5b-num-03','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Sin calcular ambos productos completos, decide cuál es mayor: 39×51 o 40×50.","steps":["40×50=2 000.","39×51=(40−1)(50+1).","Al expandir: 2 000+40−50−1=1 989."],"answer":"40×50 es mayor por 11","skill":"Argumentar","level":"Desafío","strategy":"Compara usando números cercanos.","verification":"2 000−1 989=11."},{"problem":"Un libro tiene 36 páginas de ejercicios y cada página contiene 27 problemas. Si se resuelven 18 problemas por día, ¿cuántos días se necesitan?","steps":["Total de problemas: 36×27=972.","Días: 972÷18.","18×54=972."],"answer":"54 días","skill":"Modelar","level":"Desafío","strategy":"Resuelve primero el total y luego la tasa diaria.","verification":"54×18 recupera los 972 problemas."}]}'::jsonb,9),
('school-5b-num-03','guided_practice','Práctica guiada','','{"exercises":[{"problem":"Calcula 42×16.","hints":["Descompón 16 en 10+6.","Calcula 42×10 y 42×6."],"steps":["420+252=672."],"answer":"672","skill":"Resolver problemas"},{"problem":"Estima y calcula 58×21.","hints":["Estima con 60×20.","Luego usa 58×(20+1)."],"steps":["Estimación: 1 200.","Exacto: 1 160+58=1 218."],"answer":"1 218","skill":"Resolver problemas"},{"problem":"Hay 24 cajas con 35 lápices cada una. ¿Cuántos lápices hay?","hints":["Modela 24×35.","Puedes usar 35×(20+4)."],"steps":["700+140=840."],"answer":"840 lápices","skill":"Modelar"}]}'::jsonb,10),
('school-5b-num-03','common_errors','Errores frecuentes','','{"items":[{"title":"Olvidar el valor de las decenas","description":"Multiplicar por 30 no es multiplicar por 3."},{"title":"Sumar mal los productos parciales","description":"Alinea unidades con unidades y decenas con decenas."},{"title":"No estimar","description":"Un producto como 47×32 no puede ser 150 ni 15 040."},{"title":"Responder sin unidad","description":"En un problema debes indicar asientos, lápices, pesos u otra unidad."}]}'::jsonb,11),
('school-5b-num-03','summary','Dominio esperado','','{"items":["Estimas productos antes de calcular.","Relacionas modelo de área, productos parciales y algoritmo.","Multiplicas números de dos dígitos.","Detectas errores mediante estimación.","Modelas situaciones de grupos iguales."]}'::jsonb,12),
('school-5b-num-03','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13),
('school-5b-num-04','objective','Meta de aprendizaje','Resolver divisiones y decidir si el resto se ignora, se conserva o exige aumentar el cociente.','{}'::jsonb,1),
('school-5b-num-04','prerequisites','Antes de comenzar','','{"items":[{"title":"Relación multiplicación-división","body":"Si 7×8=56, entonces 56÷7=8."},{"title":"Valor posicional","body":"El algoritmo reparte centenas, decenas y unidades."},{"title":"Estimación","body":"Ayuda a anticipar el cociente."}]}'::jsonb,2),
('school-5b-num-04','text','El resto no tiene una interpretación única','Dividir puede significar repartir una cantidad en grupos iguales o averiguar cuántos grupos caben. En 157÷6, el cociente es 26 y el resto 1 porque 6×26+1=157.

El contexto decide qué hacer con el resto. Si se forman equipos completos, el resto puede quedar fuera. Si se necesitan buses para transportar a todas las personas, un resto obliga a contratar un bus adicional. Si se reparte una cantidad medible, el resto puede expresarse como fracción o decimal.

Siempre comprueba con la relación: divisor × cociente + resto = dividendo, y verifica que el resto sea menor que el divisor.','{}'::jsonb,3),
('school-5b-num-04','concepts','Elementos de una división','','{"items":[{"title":"Dividendo","body":"Cantidad total que se reparte o agrupa."},{"title":"Divisor","body":"Tamaño de cada grupo o número de grupos."},{"title":"Cociente","body":"Resultado principal de la división."},{"title":"Resto","body":"Cantidad que no alcanza para formar otro grupo completo."}]}'::jsonb,4),
('school-5b-num-04','formula','Relación fundamental','','{"items":["Dividendo = divisor × cociente + resto","0 ≤ resto < divisor","157 = 6×26 + 1"]}'::jsonb,5),
('school-5b-num-04','strategy','Método para problemas de división','','{"steps":[{"title":"1. Identifica total y tamaño de grupo","body":"Decide qué representa cada número."},{"title":"2. Estima el cociente","body":"Usa múltiplos cercanos."},{"title":"3. Divide y comprueba","body":"Multiplica cociente por divisor y agrega el resto."},{"title":"4. Interpreta el resto","body":"Pregunta qué significa físicamente en el contexto."}]}'::jsonb,6),
('school-5b-num-04','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"Calcula 648÷6.","steps":["6 cabe en 64 diez veces y sobran 4 decenas.","Bajamos el 8: 48÷6=8.","El cociente es 108."],"answer":"108","skill":"Resolver problemas","level":"Fundamental","strategy":"Estima: 600÷6=100.","verification":"6×108=648."},{"problem":"Calcula 157÷6 e identifica el resto.","steps":["6×26=156.","157−156=1.","El resto es menor que 6."],"answer":"26, resto 1","skill":"Resolver problemas","level":"Fundamental","strategy":"Busca el mayor múltiplo que no supere el dividendo.","verification":"6×26+1=157."}]}'::jsonb,7),
('school-5b-num-04','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Hay 157 estudiantes y cada bus lleva 40. ¿Cuántos buses se necesitan?","steps":["157÷40=3 y sobran 37 estudiantes.","Tres buses solo trasladan 120 personas.","Se necesita un cuarto bus para quienes sobran."],"answer":"4 buses","skill":"Modelar","level":"Intermedio","strategy":"En transporte, un resto exige otro vehículo.","verification":"4 buses ofrecen 160 cupos, suficientes para 157."},{"problem":"Con 157 estudiantes se forman equipos de 6. ¿Cuántos equipos completos se forman y cuántos quedan fuera?","steps":["157÷6=26 resto 1.","El cociente cuenta equipos completos.","El resto cuenta estudiantes sin equipo."],"answer":"26 equipos y 1 estudiante fuera","skill":"Modelar","level":"Intermedio","strategy":"Aquí no se redondea hacia arriba porque se piden equipos completos.","verification":"26×6+1=157."}]}'::jsonb,8),
('school-5b-num-04','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Una cinta de 95 cm se corta en trozos de 8 cm. ¿Cuántos trozos completos se obtienen y cuánta cinta sobra?","steps":["95÷8=11 resto 7.","Cada uno de los 11 trozos mide 8 cm.","La parte restante mide 7 cm."],"answer":"11 trozos y sobran 7 cm","skill":"Modelar","level":"Desafío","strategy":"El resto conserva la misma unidad del dividendo.","verification":"11×8+7=95."},{"problem":"Un número dividido por 7 da cociente 34 y resto 5. ¿Cuál es el número?","steps":["Usamos dividendo=divisor×cociente+resto.","7×34=238.","238+5=243."],"answer":"243","skill":"Argumentar","level":"Desafío","strategy":"Reconstruye la división con la relación fundamental.","verification":"243÷7=34 resto 5."}]}'::jsonb,9),
('school-5b-num-04','guided_practice','Práctica guiada','','{"exercises":[{"problem":"Calcula 735÷5.","hints":["Estima 700÷5.","Comprueba multiplicando."],"steps":["735÷5=147.","147×5=735."],"answer":"147","skill":"Resolver problemas"},{"problem":"Hay 98 personas y mesas para 6. ¿Cuántas mesas se requieren para sentarlas a todas?","hints":["Calcula 98÷6.","Decide qué hacer con el resto."],"steps":["98÷6=16 resto 2.","Se necesita una mesa adicional."],"answer":"17 mesas","skill":"Modelar"},{"problem":"Se reparten 98 fichas entre 6 grupos. ¿Cuántas recibe cada grupo y cuántas sobran?","hints":["Usa la misma división anterior.","Aquí se informa el resto."],"steps":["98÷6=16 resto 2."],"answer":"16 fichas por grupo y sobran 2","skill":"Modelar"}]}'::jsonb,10),
('school-5b-num-04','common_errors','Errores frecuentes','','{"items":[{"title":"Redondear siempre hacia arriba","description":"Solo se hace cuando el contexto exige cubrir a todos o usar una unidad completa adicional."},{"title":"Aceptar un resto mayor que el divisor","description":"Si el resto es igual o mayor, todavía puede formarse otro grupo."},{"title":"No comprobar","description":"Usa divisor×cociente+resto."},{"title":"Confundir reparto con agrupamiento","description":"En ambos se divide, pero la interpretación de divisor y cociente cambia."}]}'::jsonb,11),
('school-5b-num-04','summary','Dominio esperado','','{"items":["Resuelves divisiones con dividendos de tres dígitos.","Compruebas mediante multiplicación.","Interpretas el resto según el contexto.","Decides cuándo aumentar el cociente.","Reconstruyes un dividendo con divisor, cociente y resto."]}'::jsonb,12),
('school-5b-num-04','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13),
('school-5b-num-05','objective','Meta de aprendizaje','Resolver expresiones combinadas y explicar el orden de cada paso.','{}'::jsonb,1),
('school-5b-num-05','prerequisites','Antes de comenzar','','{"items":[{"title":"Cuatro operaciones","body":"Debes calcular sumas, restas, multiplicaciones y divisiones."},{"title":"Significado de paréntesis","body":"Indican una operación que debe resolverse como unidad."},{"title":"Estimación","body":"Permite comprobar el tamaño final."}]}'::jsonb,2),
('school-5b-num-05','text','Una convención para que todos obtengan lo mismo','La expresión 8+3×4 puede dar 44 si se suma primero o 20 si se multiplica primero. Para evitar ambigüedad, se usa una convención: primero paréntesis; luego multiplicaciones y divisiones; finalmente sumas y restas. Entre operaciones del mismo nivel se avanza de izquierda a derecha.

Los paréntesis no son decoración. Cambian el significado: (8+3)×4=44, mientras que 8+3×4=20.

Una buena resolución escribe una expresión nueva después de cada paso y evita hacer varios cambios simultáneamente.','{}'::jsonb,3),
('school-5b-num-05','concepts','Niveles de prioridad','','{"items":[{"title":"1. Paréntesis","body":"Resuelve primero las agrupaciones internas."},{"title":"2. Multiplicación y división","body":"Tienen la misma prioridad y se resuelven de izquierda a derecha."},{"title":"3. Adición y sustracción","body":"También se resuelven de izquierda a derecha."},{"title":"Registro ordenado","body":"Una línea por transformación reduce errores."}]}'::jsonb,4),
('school-5b-num-05','formula','Orden convencional','','{"items":["( ) primero","× y ÷ después, de izquierda a derecha","+ y − al final, de izquierda a derecha"]}'::jsonb,5),
('school-5b-num-05','strategy','Método de tres colores','','{"steps":[{"title":"1. Encierra paréntesis","body":"Resuelve su contenido."},{"title":"2. Marca multiplicaciones y divisiones","body":"Calcula de izquierda a derecha."},{"title":"3. Completa sumas y restas","body":"Mantén el orden de izquierda a derecha."},{"title":"4. Estima y revisa","body":"Comprueba que no omitiste ningún término."}]}'::jsonb,6),
('school-5b-num-05','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"Calcula 8+3×4.","steps":["Primero 3×4=12.","La expresión queda 8+12.","Sumamos."],"answer":"20","skill":"Resolver problemas","level":"Fundamental","strategy":"La multiplicación tiene prioridad.","verification":"El resultado no es 44 porque no hay paréntesis alrededor de 8+3."},{"problem":"Calcula (8+3)×4.","steps":["Primero el paréntesis: 8+3=11.","Luego 11×4."],"answer":"44","skill":"Resolver problemas","level":"Fundamental","strategy":"Los paréntesis cambian el orden.","verification":"44 es cuatro grupos de 11."}]}'::jsonb,7),
('school-5b-num-05','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Calcula 48÷6×3.","steps":["División y multiplicación tienen igual prioridad.","Resolvemos de izquierda a derecha: 48÷6=8.","Luego 8×3=24."],"answer":"24","skill":"Argumentar","level":"Intermedio","strategy":"No se multiplica 6×3 primero sin paréntesis.","verification":"48÷18 no representa la expresión original."},{"problem":"Calcula 100−(24+6×5).","steps":["Dentro del paréntesis, primero 6×5=30.","Luego 24+30=54.","Finalmente 100−54=46."],"answer":"46","skill":"Resolver problemas","level":"Intermedio","strategy":"Los paréntesis también contienen su propia prioridad.","verification":"54+46=100."}]}'::jsonb,8),
('school-5b-num-05','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Inserta paréntesis en 12−4×2 para obtener 16.","steps":["Sin paréntesis resulta 12−8=4.","Para obtener 16 necesitamos sumar implícitamente mediante una resta previa: (12−4)×2.","8×2=16."],"answer":"(12−4)×2 = 16","skill":"Argumentar","level":"Desafío","strategy":"Prueba qué operación debe ocurrir primero.","verification":"La expresión con paréntesis mantiene los mismos números y operaciones."},{"problem":"Una tienda prepara 6 cajas con 12 cuadernos y luego vende 15. Escribe y resuelve una expresión.","steps":["Primero se preparan 6 grupos de 12: 6×12.","Luego se restan los 15 vendidos.","6×12−15=72−15."],"answer":"57 cuadernos","skill":"Modelar","level":"Desafío","strategy":"Traduce la secuencia de acciones a operaciones.","verification":"57+15=72, la cantidad inicial."}]}'::jsonb,9),
('school-5b-num-05','guided_practice','Práctica guiada','','{"exercises":[{"problem":"Calcula 30−4×5.","hints":["Haz la multiplicación antes de la resta."],"steps":["4×5=20.","30−20=10."],"answer":"10","skill":"Resolver problemas"},{"problem":"Calcula (30−4)×5.","hints":["Resuelve primero el paréntesis."],"steps":["30−4=26.","26×5=130."],"answer":"130","skill":"Resolver problemas"},{"problem":"Calcula 72÷(3×4)+5.","hints":["Resuelve el paréntesis.","Luego división y finalmente suma."],"steps":["3×4=12.","72÷12=6.","6+5=11."],"answer":"11","skill":"Resolver problemas"}]}'::jsonb,10),
('school-5b-num-05','common_errors','Errores frecuentes','','{"items":[{"title":"Resolver siempre de izquierda a derecha","description":"Solo aplica entre operaciones del mismo nivel."},{"title":"Creer que multiplicación siempre va antes que división","description":"Tienen igual prioridad y se resuelven de izquierda a derecha."},{"title":"Ignorar prioridad dentro de paréntesis","description":"Dentro de un paréntesis también se aplica el orden de operaciones."},{"title":"Hacer varios pasos en una línea","description":"Aumenta la posibilidad de omitir o modificar términos."}]}'::jsonb,11),
('school-5b-num-05','summary','Dominio esperado','','{"items":["Resuelves paréntesis primero.","Aplicas multiplicación y división antes de suma y resta.","Trabajas de izquierda a derecha en el mismo nivel.","Reconoces cómo los paréntesis cambian un resultado.","Modelas situaciones con expresiones combinadas."]}'::jsonb,12),
('school-5b-num-05','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13),
('school-5b-num-06','objective','Meta de aprendizaje','Reconocer datos esenciales, construir un plan de varias etapas, resolverlo y justificar la respuesta.','{}'::jsonb,1),
('school-5b-num-06','prerequisites','Antes de comenzar','','{"items":[{"title":"Cuatro operaciones","body":"Debes interpretar cuándo sumar, restar, multiplicar o dividir."},{"title":"Operatoria combinada","body":"Permite expresar varias etapas en una sola expresión."},{"title":"Lectura comprensiva","body":"Distingue datos útiles, pregunta y condiciones."}]}'::jsonb,2),
('school-5b-num-06','text','Resolver no es buscar palabras clave','Las palabras “en total” o “repartir” pueden orientar, pero no reemplazan la comprensión. Un problema se resuelve entendiendo relaciones: qué cantidad cambia, qué se repite, qué se compara y qué se desconoce.

Los problemas de varias etapas requieren resultados intermedios. Conviene representar con un esquema, tabla, dibujo o expresión. Cada resultado debe tener significado y unidad.

Una solución completa incluye: datos esenciales, estrategia, cálculos, respuesta y comprobación. También debes evaluar si la respuesta es razonable y si el resto de una división cambia la decisión.','{}'::jsonb,3),
('school-5b-num-06','concepts','Preguntas para comprender','','{"items":[{"title":"¿Qué sé?","body":"Lista solo los datos necesarios."},{"title":"¿Qué debo averiguar?","body":"Reescribe la pregunta con tus palabras."},{"title":"¿Qué relación existe?","body":"Cambio, comparación, grupos iguales, reparto o combinación."},{"title":"¿Cómo comprobaré?","body":"Usa operación inversa, estimación o sustitución."}]}'::jsonb,4),
('school-5b-num-06','formula','Estructuras frecuentes','','{"items":["Total = cantidad de grupos × elementos por grupo","Diferencia = cantidad mayor − cantidad menor","Cantidad por grupo = total ÷ número de grupos","Costo final = ingresos − gastos o precio × cantidad"]}'::jsonb,5),
('school-5b-num-06','strategy','Método MathLabs de cinco pasos','','{"steps":[{"title":"1. Comprende","body":"Marca pregunta, datos y condiciones."},{"title":"2. Representa","body":"Usa esquema, tabla o expresión."},{"title":"3. Planifica","body":"Ordena las operaciones antes de calcular."},{"title":"4. Resuelve","body":"Registra resultados intermedios con unidad."},{"title":"5. Comprueba y comunica","body":"Verifica y responde con una oración completa."}]}'::jsonb,6),
('school-5b-num-06','examples','Ejercicios resueltos: nivel fundamental','','{"examples":[{"problem":"Una biblioteca tenía 1 250 libros, recibió 375 y prestó 148. ¿Cuántos quedan?","steps":["Primero agregamos los recibidos: 1 250+375=1 625.","Luego restamos los prestados: 1 625−148.","El resultado es 1 477."],"answer":"1 477 libros","skill":"Modelar","level":"Fundamental","strategy":"Respeta el orden temporal de los cambios.","verification":"1 477+148=1 625."},{"problem":"Hay 18 cajas con 24 botellas. ¿Cuántas botellas hay?","steps":["Son 18 grupos iguales de 24.","Calculamos 18×24=432."],"answer":"432 botellas","skill":"Modelar","level":"Fundamental","strategy":"Grupos iguales indican multiplicación.","verification":"432÷18=24."}]}'::jsonb,7),
('school-5b-num-06','examples','Ejercicios resueltos: nivel intermedio','','{"examples":[{"problem":"Una escuela compra 28 paquetes de 35 cuadernos y reparte 760. ¿Cuántos quedan?","steps":["Total comprado: 28×35=980.","Restamos los repartidos: 980−760=220."],"answer":"220 cuadernos","skill":"Modelar","level":"Intermedio","strategy":"Calcula primero la cantidad inicial total.","verification":"220+760=980."},{"problem":"Se deben trasladar 286 personas en buses de 45 pasajeros. ¿Cuántos buses se necesitan?","steps":["286÷45=6 resto 16.","Seis buses llevan 270 personas.","Las 16 restantes necesitan otro bus."],"answer":"7 buses","skill":"Modelar","level":"Intermedio","strategy":"Interpreta el resto según el contexto.","verification":"7×45=315 cupos; 6×45 no alcanza."}]}'::jsonb,8),
('school-5b-num-06','examples','Ejercicios resueltos: desafío','','{"examples":[{"problem":"Camila tiene $25 000. Compra 3 libros de $4 800 y 2 cuadernos de $1 350. ¿Cuánto dinero le queda?","steps":["Costo libros: 3×4 800=14 400.","Costo cuadernos: 2×1 350=2 700.","Gasto total: 17 100; saldo: 25 000−17 100."],"answer":"$7 900","skill":"Modelar","level":"Desafío","strategy":"Construye una expresión: 25 000−(3×4 800+2×1 350).","verification":"7 900+17 100=25 000."},{"problem":"Un club reúne $486 000 vendiendo entradas de $6 000. Si cada función permite 27 asistentes, ¿cuántas funciones completas se realizaron y cuántas personas asistieron en total?","steps":["Entradas vendidas: 486 000÷6 000=81.","Funciones completas: 81÷27=3.","Personas totales: 81."],"answer":"3 funciones completas y 81 asistentes","skill":"Modelar","level":"Desafío","strategy":"Separa dinero→entradas y entradas→funciones.","verification":"3×27=81 y 81×6 000=486 000."}]}'::jsonb,9),
('school-5b-num-06','guided_practice','Práctica guiada','','{"exercises":[{"problem":"Una fábrica produce 32 cajas con 48 piezas y descarta 95 piezas. ¿Cuántas quedan?","hints":["Calcula primero la producción total.","Después resta lo descartado."],"steps":["32×48=1 536.","1 536−95=1 441."],"answer":"1 441 piezas","skill":"Modelar"},{"problem":"Un curso reúne $180 000. Compra 24 entradas de $6 500. ¿Cuánto sobra?","hints":["Calcula el costo de las entradas.","Resta al dinero reunido."],"steps":["24×6 500=156 000.","180 000−156 000=24 000."],"answer":"$24 000","skill":"Modelar"},{"problem":"Se empacan 743 naranjas en bolsas de 8. ¿Cuántas bolsas completas y cuántas naranjas sobran?","hints":["Divide 743 entre 8.","Interpreta cociente y resto."],"steps":["743÷8=92 resto 7."],"answer":"92 bolsas y sobran 7 naranjas","skill":"Modelar"}]}'::jsonb,10),
('school-5b-num-06','common_errors','Errores frecuentes','','{"items":[{"title":"Usar todos los números sin comprender","description":"Un problema puede incluir datos irrelevantes."},{"title":"Elegir operación por una palabra","description":"La misma palabra puede aparecer en relaciones distintas."},{"title":"Omitir resultados intermedios","description":"En problemas de varias etapas, cada cálculo cumple una función."},{"title":"No responder la pregunta final","description":"El cálculo debe traducirse a una oración con unidad y contexto."}]}'::jsonb,11),
('school-5b-num-06','summary','Dominio esperado','','{"items":["Identificas datos esenciales y pregunta.","Representas relaciones antes de calcular.","Planificas problemas de varias etapas.","Interpretas resultados y restos.","Compruebas y comunicas una respuesta completa."]}'::jsonb,12),
('school-5b-num-06','practice','Practica este tema','Continúa con una sesión adaptativa de ejercicios.','{}'::jsonb,13);

