 code text, course_id text, topic_id text, prompt text, options jsonb, correct_option text,
 explanation text, feedback_by_option jsonb, difficulty text, skill text, sort_order integer, is_published boolean
)
on conflict (code) do update set course_id=excluded.course_id, topic_id=excluded.topic_id, prompt=excluded.prompt, options=excluded.options, correct_option=excluded.correct_option, explanation=excluded.explanation, feedback_by_option=excluded.feedback_by_option, difficulty=excluded.difficulty, skill=excluded.skill, sort_order=excluded.sort_order, is_published=excluded.is_published;

-- RPC: iniciar práctica.
create or replace function public.start_school_practice(p_topic_slug text, p_question_count integer default 8)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_user uuid := auth.uid();
  v_topic public.knowledge_topics%rowtype;
  v_session uuid;
  v_available integer;
  v_count integer;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  if p_question_count < 4 or p_question_count > 12 then raise exception 'La cantidad debe estar entre 4 y 12'; end if;

  select * into v_topic from public.knowledge_topics
  where slug = p_topic_slug and is_published = true;
  if not found then raise exception 'Tema no encontrado'; end if;

  select count(*) into v_available from public.school_practice_items
  where topic_id = v_topic.id and is_published = true;
  if v_available < 4 then raise exception 'Este tema todavía no tiene suficientes preguntas'; end if;
  v_count := least(p_question_count, v_available);

  insert into public.school_practice_sessions(user_id,course_id,topic_id,total_questions)
  values(v_user,v_topic.course_id,v_topic.id,v_count) returning id into v_session;

  insert into public.school_practice_session_items(session_id,item_id,position)
  select v_session,id,row_number() over(order by md5(id::text || v_session::text))
  from public.school_practice_items
  where topic_id=v_topic.id and is_published=true
  order by md5(id::text || v_session::text)
  limit v_count;

  return jsonb_build_object('session_id',v_session,'topic_id',v_topic.id,'topic_title',v_topic.title,'total_questions',v_count);
end;
$function$;

-- RPC: obtener siguiente pregunta sin exponer respuesta.
create or replace function public.get_school_practice_question(p_session_id uuid)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_user uuid := auth.uid();
  v_session public.school_practice_sessions%rowtype;
  v_item public.school_practice_items%rowtype;
  v_item_id uuid;
  v_position integer;
  v_answered integer;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  select * into v_session from public.school_practice_sessions where id=p_session_id and user_id=v_user;
  if not found then raise exception 'Sesión no encontrada'; end if;
  if v_session.status <> 'active' then return jsonb_build_object('complete',true,'session_id',p_session_id); end if;

  select count(*) into v_answered from public.school_practice_responses where session_id=p_session_id;
  select si.item_id, si.position
    into v_item_id, v_position
  from public.school_practice_session_items si
  where si.session_id = p_session_id
    and not exists (
      select 1
      from public.school_practice_responses r
      where r.session_id = si.session_id
        and r.item_id = si.item_id
    )
  order by si.position
  limit 1;

  if found then
    select *
      into v_item
    from public.school_practice_items
    where id = v_item_id;
  end if;

  if not found then return jsonb_build_object('complete',true,'session_id',p_session_id,'answered_questions',v_answered,'total_questions',v_session.total_questions); end if;
  return jsonb_build_object('complete',false,'session_id',p_session_id,'item_id',v_item.id,'code',v_item.code,'prompt',v_item.prompt,'options',v_item.options,'difficulty',v_item.difficulty,'skill',v_item.skill,'position',v_position,'answered_questions',v_answered,'total_questions',v_session.total_questions);
end;
$function$;

-- RPC: responder y revelar retroalimentación solo después del intento.
create or replace function public.submit_school_practice_answer(p_session_id uuid,p_item_id uuid,p_selected_option text,p_confidence_level text default 'unsure',p_time_seconds integer default 0)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_user uuid := auth.uid();
  v_session public.school_practice_sessions%rowtype;
  v_item public.school_practice_items%rowtype;
  v_correct boolean;
  v_feedback text;
  v_answered integer;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  if p_selected_option not in ('A','B','C','D') then raise exception 'Alternativa inválida'; end if;
  if p_confidence_level not in ('unsure','somewhat','confident') then raise exception 'Confianza inválida'; end if;

  select * into v_session from public.school_practice_sessions where id=p_session_id and user_id=v_user and status='active';
  if not found then raise exception 'Sesión activa no encontrada'; end if;
  select i.* into v_item from public.school_practice_items i join public.school_practice_session_items si on si.item_id=i.id where si.session_id=p_session_id and i.id=p_item_id;
  if not found then raise exception 'Pregunta no pertenece a la sesión'; end if;

  v_correct := p_selected_option=v_item.correct_option;
  v_feedback := coalesce(v_item.feedback_by_option->>p_selected_option,v_item.explanation);

  insert into public.school_practice_responses(session_id,item_id,user_id,selected_option,is_correct,confidence_level,time_seconds)
  values(p_session_id,p_item_id,v_user,p_selected_option,v_correct,p_confidence_level,greatest(0,least(p_time_seconds,7200)))
  on conflict(session_id,item_id) do nothing;

  if not found then
    return jsonb_build_object('saved',false,'already_answered',true);
  end if;

  update public.school_practice_sessions set correct_answers=correct_answers + case when v_correct then 1 else 0 end where id=p_session_id;
  select count(*) into v_answered from public.school_practice_responses where session_id=p_session_id;
  return jsonb_build_object('saved',true,'is_correct',v_correct,'correct_option',v_item.correct_option,'explanation',v_item.explanation,'feedback',v_feedback,'answered_questions',v_answered,'total_questions',v_session.total_questions);
end;
$function$;

-- RPC: completar, actualizar dominio y cerrar recomendación.
create or replace function public.complete_school_practice(p_session_id uuid)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_user uuid := auth.uid();
  v_session public.school_practice_sessions%rowtype;
  v_answered integer;
  v_correct integer;
  v_score integer;
  v_confidence integer;
  v_mastery integer;
  v_status text;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  select * into v_session from public.school_practice_sessions where id=p_session_id and user_id=v_user;
  if not found then raise exception 'Sesión no encontrada'; end if;

  if v_session.status='completed' then
    v_mastery := v_session.score_percent;
    v_confidence := 0;
    v_status := case when v_mastery>=80 then 'mastered' when v_mastery>=60 then 'practicing' else 'learning' end;
    select mastery_percent,confidence_percent,status
      into v_mastery,v_confidence,v_status
    from public.student_topic_mastery
    where user_id=v_user and topic_id=v_session.topic_id;
    if not found then
      v_mastery := v_session.score_percent;
      v_confidence := 0;
      v_status := case when v_mastery>=80 then 'mastered' when v_mastery>=60 then 'practicing' else 'learning' end;
    end if;
    return jsonb_build_object('session_id',p_session_id,'completed',true,'score_percent',v_session.score_percent,'correct_answers',v_session.correct_answers,'total_questions',v_session.total_questions,'confidence_percent',v_confidence,'mastery_percent',v_mastery,'mastery_status',v_status);
  end if;
  if v_session.status<>'active' then raise exception 'La sesión no está activa'; end if;

  select count(*)::integer,count(*) filter(where is_correct)::integer,coalesce(round(avg(case confidence_level when 'confident' then 100 when 'somewhat' then 65 else 30 end)),0)::integer
  into v_answered,v_correct,v_confidence
  from public.school_practice_responses where session_id=p_session_id;
  if v_answered < v_session.total_questions then raise exception 'Aún faltan preguntas por responder'; end if;

  v_score := round(v_correct*100.0/greatest(v_session.total_questions,1));
  v_mastery := least(100,round(v_score*0.75 + v_confidence*0.10 + 15));
  v_status := case when v_mastery>=80 then 'mastered' when v_mastery>=60 then 'practicing' else 'learning' end;

  update public.school_practice_sessions set status='completed',correct_answers=v_correct,score_percent=v_score,completed_at=coalesce(completed_at,now()) where id=p_session_id;

  insert into public.student_topic_mastery(user_id,topic_id,mastery_percent,confidence_percent,attempts_count,correct_count,status,last_practiced_at,next_review_at)
  values(v_user,v_session.topic_id,v_mastery,v_confidence,v_answered,v_correct,v_status,now(),current_date + case when v_mastery>=80 then 14 when v_mastery>=60 then 7 else 3 end)
  on conflict(user_id,topic_id) do update set
    mastery_percent=greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent),
    confidence_percent=round((public.student_topic_mastery.confidence_percent + excluded.confidence_percent)/2.0),
    attempts_count=public.student_topic_mastery.attempts_count+excluded.attempts_count,
    correct_count=public.student_topic_mastery.correct_count+excluded.correct_count,
    status=case when greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent)>=80 then 'mastered' when greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent)>=60 then 'practicing' else 'learning' end,
    last_practiced_at=now(),next_review_at=excluded.next_review_at;

  update public.student_study_recommendations
  set status=case when v_mastery>=80 then 'completed' else 'in_progress' end,updated_at=now()
  where user_id=v_user and topic_id=v_session.topic_id and status in ('pending','in_progress');

  return jsonb_build_object('session_id',p_session_id,'completed',true,'score_percent',v_score,'correct_answers',v_correct,'total_questions',v_session.total_questions,'confidence_percent',v_confidence,'mastery_percent',v_mastery,'mastery_status',v_status);
end;
$function$;

-- Al completar una lección escolar, registrar evidencia básica de aprendizaje.
create or replace function public.sync_school_lesson_to_mastery()
returns trigger language plpgsql security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_topic text;
  v_mastery integer;
begin
  if new.status='completed' and (tg_op='INSERT' or (tg_op='UPDATE' and old.status is distinct from 'completed')) then
    select topic_id into v_topic from public.lesson_curriculum_links where lesson_id=new.lesson_id and topic_id is not null limit 1;
    if v_topic is not null then
      v_mastery := least(70,greatest(35,35 + coalesce(new.best_quiz_score,0)*35/100));
      insert into public.student_topic_mastery(user_id,topic_id,mastery_percent,confidence_percent,attempts_count,correct_count,status,last_practiced_at,next_review_at)
      values(new.user_id,v_topic,v_mastery,0,0,0,'learning',now(),current_date+3)
      on conflict(user_id,topic_id) do update set mastery_percent=greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent),status=case when greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent)>=80 then 'mastered' when greatest(public.student_topic_mastery.mastery_percent,excluded.mastery_percent)>=60 then 'practicing' else 'learning' end,last_practiced_at=now();
      update public.student_study_recommendations set status='in_progress',updated_at=now() where user_id=new.user_id and topic_id=v_topic and status='pending';
    end if;
  end if;
  return new;
end;
$function$;
drop trigger if exists lesson_progress_school_mastery on public.lesson_progress;
create trigger lesson_progress_school_mastery after insert or update of status on public.lesson_progress for each row execute function public.sync_school_lesson_to_mastery();

-- Permisos de funciones.
revoke all on function public.start_school_practice(text,integer) from public,anon,authenticated;
revoke all on function public.get_school_practice_question(uuid) from public,anon,authenticated;
revoke all on function public.submit_school_practice_answer(uuid,uuid,text,text,integer) from public,anon,authenticated;
revoke all on function public.complete_school_practice(uuid) from public,anon,authenticated;
revoke all on function public.sync_school_lesson_to_mastery() from public,anon,authenticated;
grant execute on function public.start_school_practice(text,integer) to authenticated;
grant execute on function public.get_school_practice_question(uuid) to authenticated;
grant execute on function public.submit_school_practice_answer(uuid,uuid,text,text,integer) to authenticated;
grant execute on function public.complete_school_practice(uuid) to authenticated;

commit;